mapper.select:
select bi.id, bi.vendor_id, bi.vendor_name, bi.contact, bi.phone, bi.collect_deposit, bi.bidding_status, bi.create_time, bi.ip_address, bi.tax_price, bi.not_tax_price from tb_bidding_info bi
bi.del_flag = 0 and (bi.parent_id is null and bi.twice_quot_version = 1)
and bi.notice_id = #{query.noticeId}
and bi.scheme_id = #{query.schemeId}
and bi.bidding_status != #{query.excludeBiddingStatus}

select distinct bi.id, bi.vendor_id, bi.vendor_name, bi.contact, bi.phone, bi.collect_deposit, bi.bidding_status, bi.create_time, bi.ip_address, CASE WHEN bop.id is null or bi.id = '' THEN '未设置开标人员' ELSE '已设置开标人员' END openPeopleStatus from tb_bidding_info bi left join tb_bidding_open_people bop on bop.notice_id = bi.notice_id
bi.del_flag = 0 and bi.parent_id is null
and bi.notice_id = #{query.noticeId}
and bi.scheme_id = #{query.schemeId}
and bi.bidding_status != #{query.excludeBiddingStatus}

select bi.id, bi.notice_id, bi.scheme_id, bi.vendor_name, bi.contact, bi.phone, bi.tax_price, bi.not_tax_price, bi.twice_quot, bi.vendor_id, bi.parent_id, bi.twice_time, bi.twice_quot, bi.twice_quot_version, bi.price_change_state from tb_bidding_info bi
bi.del_flag = 0 and bi.bidding_status != 3 and (bi.parent_id is null and (bi.twice_quot_version = 1 or bi.twice_quot_version is null))
and bi.notice_id = #{query.noticeId}
and bi.scheme_id = #{query.schemeId}

select bi.id, bi.notice_id, bi.scheme_id, bi.vendor_name, bi.contact, bi.phone, bi.tax_price, bi.not_tax_price, bi.twice_quot, bi.vendor_id, bi.parent_id, bi.twice_time, bi.twice_quot, bi.twice_quot_version, bi.price_change_state from tb_bidding_info bi
bi.del_flag = 0 and bi.bidding_status != 3 and (bi.parent_id is null)
and bi.notice_id = #{query.noticeId}
and bi.scheme_id = #{query.schemeId}

select bi.id biddingInfoId, bi.vendor_name, bi.contact, bi.phone, bi.tax_price, bi.not_tax_price, bi.scheme_id, bi.notice_id,
bi.vendor_id
from tb_bidding_info bi
left join tb_tender_notice tn on tn.id = bi.notice_id

    bi.del_flag = 0 and tn.del_flag = 0
    and bi.bidding_status != #{biddingStatus}
    and tn.notice_status >= #{noticeStatus}

        and bi.notice_id = #{noticeId}
